import { useState } from 'react'
import { AlertTriangle, CheckCircle2, CircleHelp, FileSearch, Link2, ShieldAlert, Target } from 'lucide-react'

export type CorrelationSignal = { id: string; source: string; claim: string; value: string; confidence: number; weight?: number; evidenceId?: string; observedAt?: string }
export type CorrelationConflict = { id: string; entityId: string; entityLabel: string; signals: CorrelationSignal[]; recommendedAction: string; impact: number; agreement?: number; confidenceBefore?: number; confidenceAfter?: number }
export type CorrelationSummary = { conflicts: number; signals: number; sources: number; agreement: number; confidence: number }

function clamp(value: number) { return Math.max(0, Math.min(100, value)) }

export function CorrelationConflictIntelligence({ conflicts, summary, onInvestigate, onEvidence }: { conflicts: CorrelationConflict[]; summary?: CorrelationSummary; onInvestigate?: (conflict: CorrelationConflict) => void; onEvidence?: (signal: CorrelationSignal) => void }) {
  const [selectedId, setSelectedId] = useState(conflicts[0]?.id ?? null)
  const selected = conflicts.find((item) => item.id === selectedId) ?? conflicts[0]
  const derived = summary ?? { conflicts: conflicts.length, signals: conflicts.reduce((n, item) => n + item.signals.length, 0), sources: new Set(conflicts.flatMap((item) => item.signals.map((signal) => signal.source))).size, agreement: conflicts.length ? Math.round(conflicts.reduce((sum, item) => sum + Number(item.agreement ?? 0), 0) / conflicts.length) : 100, confidence: conflicts.length ? Math.round(conflicts.reduce((sum, item) => sum + Number(item.confidenceAfter ?? 0), 0) / conflicts.length) : 100 }

  if (!conflicts.length) return <section className="rounded-2xl border bg-card p-8 text-center"><CheckCircle2 className="mx-auto h-8 w-8 text-emerald-500" /><h3 className="mt-3 font-semibold">No source conflicts detected</h3><p className="mt-1 text-xs text-muted-foreground">Available signals are currently consistent enough for the assurance layer.</p></section>

  return <section className="overflow-hidden rounded-2xl border bg-card"><header className="border-b px-5 py-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><div className="flex items-center gap-2 font-semibold"><Link2 className="h-4 w-4 text-primary" /> Correlation / Conflict Intelligence</div><p className="mt-1 text-xs text-muted-foreground">Agreement → conflict → confidence impact → recommended investigation.</p></div><span className="rounded-full border px-2.5 py-1 text-[10px] font-bold uppercase">{derived.conflicts} conflicts</span></div></header><div className="grid grid-cols-2 gap-px border-b bg-border md:grid-cols-4"><Metric label="Sources" value={derived.sources} /><Metric label="Signals" value={derived.signals} /><Metric label="Agreement" value={`${derived.agreement}%`} /><Metric label="Weighted confidence" value={`${derived.confidence}%`} /></div><div className="grid lg:grid-cols-[minmax(0,1fr)_390px]"><div className="divide-y">{conflicts.map((conflict) => <button key={conflict.id} type="button" onClick={() => setSelectedId(conflict.id)} aria-pressed={conflict.id === selectedId} className={`w-full px-5 py-4 text-left transition hover:bg-muted/30 ${conflict.id === selectedId ? 'bg-primary/5' : ''}`}><div className="flex items-start gap-3"><span className="grid h-9 w-9 shrink-0 place-items-center rounded-lg border bg-background"><ShieldAlert className="h-4 w-4 text-amber-500" /></span><span className="min-w-0 flex-1"><span className="block text-xs font-semibold truncate">{conflict.entityLabel}</span><span className="mt-1 block text-[10px] text-muted-foreground">{conflict.signals.length} source signals · impact {Math.round(clamp(conflict.impact))}/100</span></span><AlertTriangle className="h-4 w-4 text-amber-500" /></div></button>)}</div><aside className="border-t bg-muted/10 p-5 lg:border-l lg:border-t-0">{selected ? <><div className="text-[10px] font-semibold uppercase tracking-[0.14em] text-muted-foreground">Conflict detail</div><h3 className="mt-2 font-semibold">{selected.entityLabel}</h3><div className="mt-4 space-y-2">{selected.signals.map((signal) => <div key={signal.id} className="rounded-xl border bg-background p-3"><div className="flex items-center justify-between gap-3"><div className="text-xs font-semibold">{signal.source}</div><span className="text-[10px] font-bold">{Math.round(clamp(signal.confidence))}%</span></div><div className="mt-1 text-[10px] text-muted-foreground">{signal.claim}: {signal.value}</div>{signal.observedAt && <div className="mt-1 text-[9px] text-muted-foreground">Observed {signal.observedAt}</div>}{onEvidence && <button type="button" onClick={(event) => { event.stopPropagation(); onEvidence(signal) }} className="mt-2 inline-flex items-center gap-1.5 text-[10px] font-semibold text-primary hover:underline"><FileSearch className="h-3 w-3" /> Inspect evidence</button>}</div>)}</div><div className="mt-4 rounded-xl border border-amber-500/20 bg-amber-500/5 p-3"><div className="flex items-center gap-2 text-xs font-semibold"><CircleHelp className="h-4 w-4 text-amber-600" /> Recommended investigation</div><p className="mt-1 text-[11px] leading-5 text-muted-foreground">{selected.recommendedAction}</p><div className="mt-3 grid grid-cols-2 gap-2 text-[10px]"><span>Agreement <b>{selected.agreement ?? '—'}%</b></span><span>Confidence after <b>{selected.confidenceAfter ?? Math.max(0, 100 - Math.round(selected.impact))}%</b></span></div></div>{onInvestigate && <button type="button" onClick={() => onInvestigate(selected)} className="mt-4 flex w-full items-center justify-center gap-2 rounded-xl bg-primary px-3 py-2.5 text-xs font-semibold text-primary-foreground"><Target className="h-3.5 w-3.5" /> Investigate conflict</button>}</> : <div className="grid min-h-[240px] place-items-center text-xs text-muted-foreground">Select a conflict to inspect its sources.</div>}</aside></div></section>
}
function Metric({ label, value }: { label: string; value: string | number }) { return <div className="bg-card p-4"><div className="text-[10px] uppercase tracking-wider text-muted-foreground">{label}</div><div className="mt-1 text-xl font-black">{value}</div></div> }
